"""
Тесты: WebRTC не сливает IP при использовании флагов блокировки.

Запуск: pytest tests/stealth/test_webrtc_leak.py -v
"""
import asyncio
import pytest
from src.stealth.browser_stealth import StealthBrowser


@pytest.mark.asyncio
async def test_webrtc_policy_flag_present():
    """Флаг --force-webrtc-ip-handling-policy должен быть в launch args."""
    # Проверяем без реального браузера — просто что StealthBrowser содержит флаг
    # Читаем browser_stealth.py и ищем строку
    import inspect
    import src.stealth.browser_stealth as module
    source = inspect.getsource(module)
    assert "force-webrtc-ip-handling-policy" in source, (
        "Флаг --force-webrtc-ip-handling-policy отсутствует в browser_stealth.py"
    )
    assert "disable_non_proxied_udp" in source, (
        "Значение disable_non_proxied_udp отсутствует"
    )


@pytest.mark.asyncio
@pytest.mark.slow  # помечаем как медленный — запускает реальный браузер
async def test_webrtc_no_local_ip_leak():
    """
    Браузер не должен раскрывать локальный IP через WebRTC ICE candidates.

    Ожидаемый результат: RTCPeerConnection.createOffer() не находит
    локальные ICE candidates с реальным IP.
    """
    async with StealthBrowser(headed=False) as browser:
        ctx = await browser.new_context()
        page = await browser.new_page(ctx)

        # JS: пытаемся собрать ICE candidates через WebRTC
        result = await page.evaluate("""async () => {
            const candidates = [];
            const pc = new RTCPeerConnection({
                iceServers: [{ urls: 'stun:stun.l.google.com:19302' }]
            });
            pc.createDataChannel('test');

            await new Promise((resolve) => {
                const timeout = setTimeout(resolve, 3000);
                pc.onicecandidate = (e) => {
                    if (e.candidate) {
                        candidates.push(e.candidate.candidate);
                    } else {
                        clearTimeout(timeout);
                        resolve();
                    }
                };
                pc.createOffer().then(o => pc.setLocalDescription(o));
            });

            pc.close();
            return candidates;
        }""")

        # С флагом disable_non_proxied_udp candidates должны быть пустыми
        # или содержать только relay (TURN) — не host/srflx с реальным IP
        local_ip_candidates = [c for c in result if "typ host" in c or "typ srflx" in c]

        assert len(local_ip_candidates) == 0, (
            f"WebRTC leak! Обнаружены local/srflx candidates: {local_ip_candidates}"
        )
        await ctx.close()


