import pytest
from unittest.mock import MagicMock, patch
from src.platforms.linkedin_voyager import LinkedInVoyager, VoyagerSession


class TestVoyagerSession:
    """Tests for VoyagerSession dataclass."""

    def test_csrf_token_strips_quotes(self):
        """CSRF token should strip quotes from JSESSIONID."""
        session = VoyagerSession(
            li_at="test_token",
            jsessionid='"ajax:12345678"',  # with quotes as in browser
        )
        headers = session.to_headers()
        # csrf-token should NOT contain quotes
        assert headers["csrf-token"] == "ajax:12345678"

    def test_cookies_dict(self):
        """Cookies dict should have li_at and JSESSIONID."""
        session = VoyagerSession(li_at="my_li_at", jsessionid="ajax:123")
        cookies = session.to_cookies()
        assert cookies["li_at"] == "my_li_at"
        assert '"ajax:123"' in cookies["JSESSIONID"]  # adds quotes for cookie

    def test_headers_content(self):
        """Headers should contain required LinkedIn API headers."""
        session = VoyagerSession(li_at="x", jsessionid="y")
        h = session.to_headers()
        assert h["x-restli-protocol-version"] == "2.0.0"
        assert "vnd.linkedin.normalized" in h["accept"]
        assert h["csrf-token"] == "y"

    def test_load_from_file(self, tmp_path):
        """Session should load from JSON file."""
        import json
        session_file = tmp_path / "linkedin_session.json"
        session_file.write_text(json.dumps({
            "li_at": "test_li_at_value",
            "jsessionid": "ajax:987654321"
        }))

        session = VoyagerSession.load(session_file)
        assert session.li_at == "test_li_at_value"
        assert session.jsessionid == "ajax:987654321"


class TestJobParsing:
    """Tests for job parsing from Voyager responses."""

    def test_parse_empty_response(self):
        """Empty response should return empty list."""
        session = VoyagerSession(li_at="x", jsessionid="y")
        voyager = LinkedInVoyager(session)
        jobs = voyager._parse_jobs({})
        assert jobs == []

    def test_parse_no_elements(self):
        """Response with no elements should return empty list."""
        session = VoyagerSession(li_at="x", jsessionid="y")
        voyager = LinkedInVoyager(session)
        jobs = voyager._parse_jobs({"data": {"elements": []}})
        assert jobs == []

    def test_parse_malformed_elements(self):
        """Should not crash on malformed data."""
        session = VoyagerSession(li_at="x", jsessionid="y")
        voyager = LinkedInVoyager(session)
        # Should not raise on invalid data
        jobs = voyager._parse_jobs({
            "data": {
                "elements": [
                    {"bad": "data"},
                    {},
                    {"jobCardUnion": {}},
                ]
            }
        })
        assert jobs == []

    def test_parse_valid_job(self):
        """Should parse valid job from Voyager response."""
        session = VoyagerSession(li_at="x", jsessionid="y")
        voyager = LinkedInVoyager(session)

        data = {
            "data": {
                "elements": [{
                    "jobCardUnion": {
                        "jobPostingCard": {
                            "jobPosting": {
                                "title": "Senior Engineer",
                                "entityUrn": "urn:li:fsd_jobPosting:3901234567",
                            },
                            "primaryDescription": {"text": "Google"},
                            "secondaryDescription": {"text": "Remote, US"},
                        }
                    }
                }]
            }
        }

        jobs = voyager._parse_jobs(data)
        assert len(jobs) == 1
        assert jobs[0].title == "Senior Engineer"
        assert jobs[0].company == "Google"
        assert jobs[0].location == "Remote, US"
        assert "3901234567" in jobs[0].url
        assert jobs[0].source == "linkedin_voyager"
        assert jobs[0].job_id == "linkedin_3901234567"

    def test_parse_multiple_jobs(self):
        """Should parse multiple jobs from response."""
        session = VoyagerSession(li_at="x", jsessionid="y")
        voyager = LinkedInVoyager(session)

        data = {
            "data": {
                "elements": [
                    {
                        "jobCardUnion": {
                            "jobPostingCard": {
                                "jobPosting": {
                                    "title": "Engineer I",
                                    "entityUrn": "urn:li:fsd_jobPosting:111",
                                },
                                "primaryDescription": {"text": "Company A"},
                                "secondaryDescription": {"text": "NYC"},
                            }
                        }
                    },
                    {
                        "jobCardUnion": {
                            "jobPostingCard": {
                                "jobPosting": {
                                    "title": "Engineer II",
                                    "entityUrn": "urn:li:fsd_jobPosting:222",
                                },
                                "primaryDescription": {"text": "Company B"},
                                "secondaryDescription": {"text": "SF"},
                            }
                        }
                    },
                ]
            }
        }

        jobs = voyager._parse_jobs(data)
        assert len(jobs) == 2
        assert jobs[0].title == "Engineer I"
        assert jobs[1].title == "Engineer II"


